[CmdletBinding(SupportsShouldProcess=$true,ConfirmImpact='High')]
param([ValidateSet('Check','Capture','DryRun','Apply','Verify','VerifyReboot','Rollback')][string]$Action='Check',[string]$StatePath=(Join-Path $PSScriptRoot 'state.json'),[string]$LogPath=(Join-Path $PSScriptRoot 'events.jsonl'))
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
$script:RecommendedPath='HKLM:\SOFTWARE\Policies\Microsoft\Edge\Recommended';$script:MandatoryPath='HKLM:\SOFTWARE\Policies\Microsoft\Edge';$script:ValueName='StartupBoostEnabled'
function Write-ExpLog([string]$Event,[string]$Result,[hashtable]$Data=@{}){$r=[ordered]@{timestampUtc=(Get-Date).ToUniversalTime().ToString('o');experiment='EXP-038';action=$Action;event=$Event;result=$Result;data=$Data};Add-Content -LiteralPath $LogPath -Value ($r|ConvertTo-Json -Compress -Depth 8) -Encoding UTF8}
function Get-EdgePath {$p=@("$env:ProgramFiles(x86)\Microsoft\Edge\Application\msedge.exe","$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe");@($p|Where-Object{$_ -and(Test-Path -LiteralPath $_)})|Select-Object -First 1}
function Get-ManagementState {$managed=$false;$signals=@();try{$t=(& dsregcmd.exe /status 2>$null)-join "`n";foreach($n in @('AzureAdJoined','DomainJoined','WorkplaceJoined')){if($t -match "(?im)^\s*$n\s*:\s*YES\s*$"){$managed=$true;$signals+=$n}}}catch{};[pscustomobject]@{Managed=$managed;Signals=$signals}}
function Get-SupportState {$os=Get-CimInstance Win32_OperatingSystem;$cs=Get-CimInstance Win32_ComputerSystem;$edge=Get-EdgePath;$v=$null;if($edge){$raw=(Get-Item -LiteralPath $edge).VersionInfo.ProductVersion;if($raw){$v=[version]$raw}};$m=Get-ManagementState;$admin=([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator);[pscustomobject]@{Supported=($os.Caption -match 'Windows 11' -and $cs.Manufacturer -match 'HP|Hewlett-Packard' -and $edge -and $v -and $v.Major -ge 88);OS=$os.Caption;Build=$os.BuildNumber;Manufacturer=$cs.Manufacturer;Model=$cs.Model;EdgePath=$edge;EdgeVersion=$(if($v){$v.ToString()}else{$null});Managed=$m.Managed;ManagementSignals=$m.Signals;Elevated=$admin}}
function Get-ValueState([string]$Path){$k=Test-Path -LiteralPath $Path;$e=$false;$d=$null;$kind=$null;if($k){$i=Get-Item -LiteralPath $Path;$e=$i.GetValueNames()-contains $script:ValueName;if($e){$d=$i.GetValue($script:ValueName,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames);$kind=$i.GetValueKind($script:ValueName).ToString()}};[pscustomobject]@{Path=$Path;KeyExists=$k;ValueExists=$e;Data=$d;Kind=$kind}}
function Save-State($s,$r,$m){$o=[ordered]@{schemaVersion=1;experiment='EXP-038';capturedUtc=(Get-Date).ToUniversalTime().ToString('o');machine=$env:COMPUTERNAME;recommendedPath=$script:RecommendedPath;mandatoryPath=$script:MandatoryPath;valueName=$script:ValueName;edgePath=$s.EdgePath;edgeVersion=$s.EdgeVersion;recommended=$r;mandatory=$m};$o|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $StatePath -Encoding UTF8;$o}
function Read-State {if(-not(Test-Path -LiteralPath $StatePath)){throw "State file missing: $StatePath"};$s=Get-Content -LiteralPath $StatePath -Raw|ConvertFrom-Json;if($s.schemaVersion-ne 1-or$s.experiment-ne'EXP-038'-or$s.machine-ne$env:COMPUTERNAME-or$s.valueName-ne$script:ValueName){throw 'State identity validation failed.'};$s}
function Assert-Safe($s,$r,$m){if(-not$s.Elevated){throw 'Elevation is required.'};if($s.Managed){throw ('Enterprise management detected: '+($s.ManagementSignals-join', '))};if($m.ValueExists-or$r.ValueExists){throw 'Existing mandatory or recommended Edge policy detected; refusing to override.'}}
function Test-Applied {$p=Get-ValueState $script:RecommendedPath;$p.ValueExists-and$p.Kind-eq'DWord'-and[int]$p.Data-eq 0}
function Restore-State($s){$c=Get-ValueState $script:RecommendedPath;if($s.recommended.ValueExists){throw 'Captured state was ineligible for application.'};if($c.ValueExists-and-not($c.Kind-eq'DWord'-and[int]$c.Data-eq 0)){throw 'Rollback refused because the policy changed after application.'};if($c.ValueExists-and$PSCmdlet.ShouldProcess("$($script:RecommendedPath)::$($script:ValueName)",'Remove experiment policy')){Remove-ItemProperty -LiteralPath $script:RecommendedPath -Name $script:ValueName};if(-not$s.recommended.KeyExists-and(Test-Path -LiteralPath $script:RecommendedPath)){if((Get-Item $script:RecommendedPath).ValueCount-eq 0-and@(Get-ChildItem $script:RecommendedPath -ErrorAction SilentlyContinue).Count-eq 0){if($PSCmdlet.ShouldProcess($script:RecommendedPath,'Remove empty experiment-created key')){Remove-Item $script:RecommendedPath -Force}}}}
try{$s=Get-SupportState;Write-ExpLog 'support-detection' $(if($s.Supported){'pass'}else{'unsupported'}) @{edgeVersion=$s.EdgeVersion;managed=$s.Managed;elevated=$s.Elevated};if(-not$s.Supported){throw 'EXP-038 supports HP Windows 11 systems with Edge 88 or later only.'};$r=Get-ValueState $script:RecommendedPath;$m=Get-ValueState $script:MandatoryPath;switch($Action){'Check'{[pscustomobject]@{Support=$s;Recommended=$r;Mandatory=$m}}'Capture'{Assert-Safe $s $r $m;Save-State $s $r $m;Write-ExpLog 'state-capture' 'pass' @{statePath=$StatePath}}'DryRun'{if((Test-Path $StatePath)-and(Test-Applied)){[void](Read-State);[pscustomobject]@{WouldChange=$false;AlreadyApplied=$true}}else{Assert-Safe $s $r $m;[pscustomobject]@{WouldSet="$($script:RecommendedPath)::$($script:ValueName)";Data=0;BrowserRestartRequired=$true;RebootPersistenceCheckRequired=$true}};Write-ExpLog 'dry-run' 'pass' @{} }'Apply'{if(Test-Path $StatePath){$st=Read-State;if(Test-Applied){Write-ExpLog 'apply' 'pass' @{changed=$false};break}}else{Assert-Safe $s $r $m;$st=Save-State $s $r $m};if($PSCmdlet.ShouldProcess("$($script:RecommendedPath)::$($script:ValueName)",'Set REG_DWORD 0')){if(-not(Test-Path $script:RecommendedPath)){New-Item $script:RecommendedPath -Force|Out-Null};New-ItemProperty -LiteralPath $script:RecommendedPath -Name $script:ValueName -PropertyType DWord -Value 0 -Force|Out-Null};if(-not(Test-Applied)){throw 'Apply verification failed.'};Write-ExpLog 'apply' 'pass' @{changed=$true;browserRestartRequired=$true}}'Verify'{$ok=Test-Applied;Write-ExpLog 'verify' $(if($ok){'pass'}else{'fail'}) @{};if(-not$ok){throw 'Policy verification failed.'};$true}'VerifyReboot'{$ok=Test-Applied;Write-ExpLog 'verify-reboot' $(if($ok){'pass'}else{'fail'}) @{bootTime=(Get-CimInstance Win32_OperatingSystem).LastBootUpTime};if(-not$ok){throw 'Reboot persistence verification failed.'};$true}'Rollback'{$st=Read-State;Restore-State $st;$p=Get-ValueState $script:RecommendedPath;$ok=-not$p.ValueExists;Write-ExpLog 'rollback' $(if($ok){'pass'}else{'fail'}) @{};if(-not$ok){throw 'Rollback verification failed.'};$true}}}catch{Write-ExpLog 'failure' 'fail' @{message=$_.Exception.Message;type=$_.Exception.GetType().FullName};throw}
